import json,base64,sys,re,html
def b(d):
    d=d.replace('-','+').replace('_','/'); d+='='*(-len(d)%4)
    return base64.b64decode(d).decode('utf-8','replace')
def walk(p):
    out=[]
    mt=p.get('mimeType','')
    data=(p.get('body') or {}).get('data')
    if data and mt.startswith('text/plain'): out.append(b(data))
    for q in p.get('parts') or []: out+=walk(q)
    if not out and data and mt.startswith('text/html'):
        t=re.sub(r'<[^>]+>',' ',b(data)); out.append(html.unescape(t))
    return out
for f in sys.argv[1:]:
